INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (2, "", 554, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は大吉！　ラッキーワードは「ぴょんぴょん♪」\nおっきな声で一緒に言ってみよ～♪　うさぎさんぴょんぴょ～ん♪");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (2, "", 555, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は大吉！　あなたの趣味がもっと広がるかも！\nかんわゆ～～～いショタと～騎士きゅんもゲット～んふふ～♪");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (2, "", 556, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～");
