INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (3, "", 559, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (3, "", 560, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (3, "", 561, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は中吉！　健康に気を遣って気持ちのいい一年を！\n体に不調があるときは遠慮なく言いなさい、隅々まで調べてあげる");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (3, "", 562, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は中吉！　歌を口ずさみ、幸運を呼び込もう！\n幸運になれるかは分からないけど……一緒に、歌いましょ？");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (3, "", 563, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は中吉！　誰かに尽くすことで掴める幸せもあるかも？\n人事を尽くして天命を待つ！　さ、年始もバリバリ働きますわよ♪");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (4, "", 564, 60004, "", 0, 0, 0, 1, 0, 2, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！");
